BASELINE_COMMIT = '43f42d83db54fb0f308aa3e2743aad872fcaf6e8'

SOURCES = {
    ('subfleet.home_paths', 'under_pytest'): 'def under_pytest(environ: Mapping[str, str] | None = None) -> bool:\n    """Whether this process, or a child given `environ`, is in a test session."""\n    values = os.environ if environ is None else environ\n    if PYTEST_MARKER in values:\n        session = values.get(PYTEST_SESSION)\n        # Bare markers remain useful for standalone test harnesses. Configured\n        # sessions always supply a lifetime, including in captured child envs.\n        # A copied PYTEST_CURRENT_TEST must not revive an expired session either.\n        if session is None:\n            return True\n        return session_alive(session, values.get(PYTEST_SESSION_ID))\n    return "PYTEST_CURRENT_TEST" in values',
    ('subfleet.home_paths', 'home_path'): 'def home_path(variable: str, default: Callable[[], str | Path], *,\n              env: Mapping[str, str] | None = None, accept_empty: bool = False,\n              test_only: bool = False, expand_override: bool = False) -> str | Path:\n    """Test-only guard against implicit access to the person\'s home stores.\n\n    On 2026-10-12 a test\'s monkeypatch.undo() undid the desktop-store fixture,\n    and the mirror rewrote the person\'s live Claude session copies. Session\n    environment isolation is the first defense; the session marker covers\n    configure, collection and teardown, when PYTEST_CURRENT_TEST is absent.\n    A live session marker or a standalone test marker makes a missing override\n    refuse the fallback before access. Cleanup expires captured session markers,\n    including copied PYTEST_CURRENT_TEST values, by deleting their sentinel.\n    Recreating a store directory cannot recreate that sentinel\'s identity.\n    test_only supplies an isolation seam for defaults that historically had no\n    environment override, preserving their behavior outside pytest. Optional\n    expansion applies only to overrides, never to an already constructed default;\n    raw overrides let other callers retain their expansion and empty handling.\n    """\n    testing = under_pytest()\n    if test_only and not testing:\n        return default()\n    values = os.environ if env is None else env\n    override = values.get(variable)\n    if override or (accept_empty and override is not None):\n        return Path(override).expanduser() if expand_override else override\n    if testing:\n        raise RuntimeError(f"Refusing personal path fallback under pytest; set {variable} "\n                           "to an isolated test path")\n    return default()',
    ('subfleet.home_paths', 'is_account_home'): 'def is_account_home(home: Path) -> bool:\n    """Whether `home` is the account\'s own home directory, by any spelling.\n\n    Equal spellings decide without a stat. Otherwise the home directories\n    themselves are compared, never a store beneath them.\n    """\n    import pwd\n\n    personal = Path(pwd.getpwuid(os.getuid()).pw_dir)\n    if home == personal:\n        return True\n    try:\n        return home.samefile(personal)\n    except OSError:\n        # An inaccessible synthetic home must still reach the spelling refusal.\n        return False',
    ('subfleet.home_paths', 'protected_provider_homes'): 'def protected_provider_homes() -> list[Path]:\n    """Protect test-provided HOME as well as isolated reader paths.\n\n    Reader overrides must remain mandatory under pytest. They redirect access,\n    but must not hide the provider homes checked by workspace admission. Only\n    a HOME distinct from the account\'s home may add those implicit paths during\n    tests; compare the home directories themselves without inspecting stores.\n    """\n    isolated = [Path(home_path("CLAUDE_CONFIG_DIR", lambda: Path.home() / ".claude",\n                               test_only=True)), codex_app_home()]\n    if not under_pytest():\n        return isolated\n    home = Path.home()\n    if is_account_home(home):\n        return isolated\n    return [home / ".claude", home / ".codex", *isolated]',
    ('subfleet.home_paths', 'production_state_root'): 'def production_state_root() -> Path:\n    """D-21: the person\'s production state root, `~/.subfleet`, resolved as\n    release/217 resolves it.\n\n    Under pytest only a test\'s own HOME may name it: the D-21 tests set HOME and\n    expect `HOME/.subfleet` to be the production root. The provider-home seam is\n    not this root, because pytest points it at the session\'s own directory, so\n    every test root would count as a development root. A HOME that is still the\n    account\'s own would resolve the person\'s live store, so it is refused before\n    anything beneath it is touched (D-ST1).\n    """\n    home = Path.home()\n    if under_pytest() and is_account_home(home):\n        raise RuntimeError("Refusing to resolve the personal state root ~/.subfleet under pytest; "\n                           "set HOME to an isolated test home")\n    return (home / ".subfleet").resolve()',
    ('subfleet.home_paths', 'codex_app_home'): 'def codex_app_home() -> Path:\n    """The desktop Codex home, with a test-only isolation override."""\n    return Path(home_path("SUBFLEET_CODEX_APP_HOME", lambda: Path.home() / ".codex",\n                          test_only=True))',
    ('subfleet.home_paths', 'desktop_login_path'): 'def desktop_login_path() -> Path:\n    """Claude\'s desktop login, with a test-only isolation override."""\n    return Path(home_path("SUBFLEET_DESKTOP_LOGIN", lambda: Path.home() / ".claude.json",\n                          test_only=True))',
    ('subfleet.home_paths', 'provider_home'): 'def provider_home() -> Path:\n    """Base of legacy provider homes, with a test-only isolation override."""\n    return Path(home_path("SUBFLEET_PROVIDER_HOME", Path.home, test_only=True))',
    ('subfleet.adapters.claude_mcp', 'global_config_path'): 'def global_config_path(env: Mapping[str, str] | None = None, home: str | Path | None = None) -> Path:\n    """The file Claude Code keeps user- and local-scope servers in (`Lo`, `M7n`)."""\n    env = os.environ if env is None else env\n    from ..home_paths import home_path, under_pytest\n    home = Path(home) if home is not None else None\n    # Release resolves HOME eagerly, even with CLAUDE_CONFIG_DIR. Keep its\n    # exceptions outside tests; under pytest, refuse implicit HOME before use.\n    if home is None and not under_pytest():\n        home = Path.home()\n    configured = env.get("CLAUDE_CONFIG_DIR")\n    if configured:\n        base = Path(configured)\n    elif home is not None:\n        base = home / ".claude"\n    else:\n        base = Path(home_path("CLAUDE_CONFIG_DIR", lambda: Path.home() / ".claude", env=env))\n    legacy = base / ".config.json"\n    if legacy.exists():\n        return legacy\n    return (base if configured else base.parent) / ".claude.json"',
    ('subfleet.compat', 'v1_binary'): 'def v1_binary(env: dict[str, str] | None = None) -> str | None:\n    """The v1 `subfleet` a delegated verb runs, or None when there is none.\n\n    Never returns this process\'s own entry point: after the symlink flip\n    `shutil.which("subfleet")` is v2, and delegating to it would recurse until\n    the process table gave out.\n    """\n    env = os.environ if env is None else env\n    candidates = [env.get(V1_BIN_ENV), V1_BIN_DEFAULT]\n    for candidate in candidates:\n        if not candidate:\n            continue\n        path = Path(candidate).expanduser()\n        if path.is_file() and os.access(path, os.X_OK):\n            return str(path)\n    found = shutil.which("subfleet")\n    if found and not _is_self(found):\n        return found\n    return None',
    ('subfleet.guard.preflight', 'guard_paths'): 'def guard_paths(state_root: str | Path | None = None, *,\n                hook_path: str | Path | None = None,\n                trust_path: str | Path | None = None) -> tuple[Path, Path]:\n    """Resolve operator-owned overlay locations without creating files.\n\n    There is deliberately no bundled or test-fixture fallback. The legacy\n    TRUST override remains supported; an explicit argument takes precedence.\n    """\n    directory = Path(state_root if state_root is not None else _state_root()).expanduser() / "guard"\n    return (Path(hook_path) if hook_path is not None else directory / "never-rules-hook.sh",\n            Path(trust_path if trust_path is not None else\n                 os.environ.get("SUBFLEET_GUARD_TRUST") or directory / "TRUST"))',
    ('subfleet.guard.preflight', 'cache_dir'): 'def cache_dir(state_root: str | Path | None = None) -> Path:\n    """``$SUBFLEET_CODEX_GUARD_CACHE`` (v1\'s name), else ``<state root>/guard-cache``.\n\n    A relative override resolves under the state root, never the process cwd\n    (C-2.1). ``state_root`` is the daemon\'s root when it has one; otherwise\n    ``$SUBFLEET_HOME``.\n    """\n    root = Path(state_root) if state_root is not None else Path(_state_root())\n    override = os.environ.get(CACHE_ENV)\n    if override:\n        path = Path(os.path.expanduser(override))\n        if path.is_absolute():\n            return path  # the operator\'s explicit choice (v1 kept markers under ~/.cache)\n        resolved = (root / path).resolve()\n        if not resolved.is_relative_to(root.resolve()):\n            raise ValueError(f"{CACHE_ENV}={override!r} is relative and leaves the state root {root}")\n        return root / path\n    return root / "guard-cache"',
    ('subfleet.credentials', 'keychain_command'): 'def keychain_command(reference: str, security_bin: str = "security", *,\n                     runner=None) -> list[str]:\n    """Keep v1\'s dedicated agent keychain when its helper is installed.\n\n    A failed helper read must not fall through to a same-named, stale credential\n    in the login keychain. Hosts without the helper retain the native backend.\n    """\n    # Provider-owned desktop/home OAuth blobs stay in their native keychain.\n    # Only the explicit per-lane setup-token namespace belongs to agent-secret.\n    if reference.startswith("claude-quota-"):\n        helper = os.environ.get("CLAUDE_LANE_AGENT_SECRET")\n        if not helper:\n            default = Path(home_path("SUBFLEET_AGENT_SECRET",\n                                     lambda: Path.home() / "bin" / "agent-secret",\n                                     test_only=True))\n            helper = str(default) if default.is_file() else None\n        if helper:\n            return [helper, "get", reference]\n    # A reference or fake HOME does not isolate macOS\'s login keychain. Fixture\n    # undo cannot remove this guard. Only a stand-in runner or executable\n    # may issue a credential command while either marker is present. This is\n    # the early refusal that explains itself; the exec guard below is the rule.\n    if (under_pytest() and (runner is None or runner is _NATIVE_RUNNER)\n            and _starts_keychain_binary(security_bin)):\n        raise AdapterError(_REFUSAL, code=7, fix=_REFUSAL_FIX, reason="keychain-test-guard")\n    return [security_bin, "find-generic-password", "-s", reference, "-w"]',
    ('subfleet.cli', '_daemond_argv'): 'def _daemond_argv(root: Path) -> list[str]:\n    """How to start `subfleetd`, honouring an explicit override for tests."""\n    override = (os.environ.get("SUBFLEET_DAEMON_BIN") or "").strip()\n    if override:\n        return [override, "--state-root", str(root)]\n    # `-E -P`: the daemon must import this package whatever PYTHON* variables the\n    # installing shell inherited (v1\'s wrapper exports PYTHONPATH=<v1 checkout>\n    # to everything it launches; decisions memo 2026-09-05 §3). A console script\n    # found on PATH or beside the interpreter is run through the interpreter for\n    # the same reason instead of being exec\'d on its own shebang.\n    isolated = [sys.executable, "-E", "-P"]\n    found = shutil.which("subfleetd")\n    if found:\n        return [*isolated, found, "--state-root", str(root)]\n    sibling = Path(sys.executable).parent / "subfleetd"\n    if sibling.exists():\n        return [*isolated, str(sibling), "--state-root", str(root)]\n    return [*isolated, "-m", "subfleet.daemon", "--state-root", str(root)]',
    ('subfleet.retention_git', 'temp_roots'): 'def temp_roots() -> set[str]:\n    """Directories whose contents the system or a person may delete at any time."""\n    return {os.path.realpath(p) for p in (*TEMP_ROOTS, tempfile.gettempdir(), os.environ.get("TMPDIR") or "/tmp")}',
    ('subfleet.conversations.service', 'ConversationService._app_executables'): 'def _app_executables(self) -> tuple[str, ...]:\n    """C-25.6, D-21: the installed app. A development daemon (any state root but\n    ~/.subfleet) also accepts the development build named when it started."""\n    dev = os.environ.get("SUBFLEET_DEV_APP_EXECUTABLE")\n    if dev and self.root.resolve() != production_state_root():\n        return (*APP_EXECUTABLES, dev)\n    return APP_EXECUTABLES',
    ('subfleet.prune_decisions', 'main'): 'def main(argv: list[str] | None = None) -> int:\n    """`python -m subfleet.prune_decisions`; the CLI keeps its own verbs."""\n    parser = argparse.ArgumentParser(\n        prog="subfleet.prune_decisions",\n        description="delete the redundant decisions rows a waiting job accumulated "\n                    "(the daemon must be stopped)")\n    parser.add_argument("--state-root", default=os.environ.get("SUBFLEET_HOME") or "~/.subfleet")\n    parser.add_argument("--backup-dir", default=None,\n                        help="where the backups go (default: <state root>/backups), "\n                             "for instance a directory on another volume")\n    parser.add_argument("--apply", action="store_true",\n                        help="delete rows; without it the pass plans and writes nothing")\n    parser.add_argument("--i-understand-this-deletes-decisions", dest="confirm",\n                        action="store_true", help="required beside --apply")\n    parser.add_argument("--vacuum", action="store_true",\n                        help="rebuild the database after the delete so the freed pages "\n                             "return to the filesystem")\n    parser.add_argument("--no-report", dest="report", action="store_false",\n                        help="print the report without saving it")\n    parser.add_argument("--json", action="store_true", help="print the report as JSON")\n    args = parser.parse_args(argv)\n    if args.apply and not args.confirm:\n        return _fail(PruneRefused.code, "prune decisions: --apply deletes rows and was not "\n                                        "confirmed",\n                     "re-run with --apply --i-understand-this-deletes-decisions")\n    try:\n        report = prune(args.state_root, apply=args.apply, confirm=args.confirm,\n                       backup_dir=args.backup_dir, vacuum=args.vacuum, write_report=args.report)\n    except PruneError as stop:\n        # Every refusal, failed proof, unhandled stop and unsaved report\n        # arrives in one shape. A pass that finished still prints its report\n        # where a finished pass does, after the record on stderr, so a stdout\n        # that cannot be written loses nothing; only the file is missing.\n        code = _fail(stop.code, str(stop), stop.fix, stop.report)\n        if isinstance(stop, PruneReportUnsaved):\n            _show(stop.report, args.json)\n        return code\n    except SchemaVersionError as mismatch:\n        # C-3.5: the store is newer than this build knows, and the message\n        # carries both versions; `Store` raises it before the pass has a report.\n        return _fail(mismatch.code, f"prune decisions: {mismatch}",\n                     "run this pass from the build that wrote the store")\n    except (sqlite3.Error, OSError) as error:\n        # Reading the schema or opening the store: everything after that comes\n        # out of `prune` as a `PruneError` carrying its report.\n        return _fail(PruneStopped.code, f"prune decisions: {type(error).__name__}: {error}",\n                     "the pass stopped before it planned, so it deleted nothing and has "\n                     "no report; fix what the error names and run it again")\n    _show(report, args.json)\n    return 0',
}
